package com.estreams.blue;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity {
 final int BG=0xff090e19,PANEL=0xff141d30,BLUE=0xff1688ff,WHITE=0xfff2f7ff,MUTED=0xffa2b3cc;
 LinearLayout root,content,nav; EditText server,user,pass; TextView status; ArrayList<Channel> channels=new ArrayList<>(); String provider="",username="",password=""; Handler handler=new Handler(Looper.getMainLooper());
 static class Channel {String name,url,group;Channel(String n,String u,String g){name=n;url=u;group=g;}}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);String saved=getPreferences(0).getString("url","");if(saved.isEmpty())login();else {provider=getPreferences(0).getString("provider","");username=getPreferences(0).getString("user","");password=getPreferences(0).getString("pass","");shell();load(saved);}}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(14,10,14,10);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void base(){root=column();root.setBackgroundColor(BG);setContentView(root);}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextColor(WHITE);b.setAllCaps(false);b.setTextSize(16);b.setBackground(shape(PANEL,14));b.setOnFocusChangeListener((v,f)->b.setBackground(shape(f?BLUE:PANEL,14)));b.setOnClickListener(v->action.run());return b;}
 EditText field(String hint,String val){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(val);e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));return e;}
 void login(){base();ScrollView sc=new ScrollView(this);root.addView(sc);LinearLayout box=column();box.setPadding(48,32,48,32);sc.addView(box);TextView title=text("E STREAMS",34,WHITE);title.setTypeface(null,Typeface.BOLD);box.addView(title);box.addView(text("BLUE  /  YOUR TV, YOUR WAY",14,BLUE));box.addView(text("Sign in with Xtream Codes or paste a direct M3U URL",17,MUTED));server=field("Server URL or full M3U URL",getPreferences(0).getString("url",""));user=field("Username (Xtream only)",getPreferences(0).getString("user",""));pass=field("Password (Xtream only)",getPreferences(0).getString("pass",""));box.addView(server);box.addView(user);box.addView(pass);status=text("",14,MUTED);box.addView(status);box.addView(button("Connect to provider",()->{String s=server.getText().toString().trim();if(s.isEmpty()){status.setText("Enter your provider URL");return;}provider=s;username=user.getText().toString().trim();password=pass.getText().toString().trim();getPreferences(0).edit().putString("url",s).putString("provider",s).putString("user",username).putString("pass",password).apply();shell();load(s);}));}
 void shell(){base();LinearLayout top=new LinearLayout(this);top.setPadding(18,12,18,12);top.setGravity(Gravity.CENTER_VERTICAL);root.addView(top);TextView brand=text("E  STREAMS",25,WHITE);brand.setTypeface(null,Typeface.BOLD);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));top.addView(text("●  BLUE",13,BLUE));nav=new LinearLayout(this);root.addView(nav);addTab("Live TV",()->browse("Live TV"));addTab("Sports",()->browse("Sports"));addTab("News",()->browse("News"));addTab("Movies",()->browse("Movies"));addTab("Series",()->browse("Series"));addTab("Settings",this::settings);content=column();root.addView(content,new LinearLayout.LayoutParams(-1,0,1));content.addView(text("Loading your provider...",20,MUTED));}
 void addTab(String name,Runnable r){Button b=button(name,r);nav.addView(b,new LinearLayout.LayoutParams(0,56,1));}
 void settings(){content.removeAllViews();content.addView(text("Settings",28,WHITE));content.addView(button("Refresh provider",()->load(provider)));content.addView(button("Change provider / sign out",()->{getPreferences(0).edit().clear().apply();channels.clear();login();}));content.addView(text("E Streams Blue v1.0 · Separate app · Provider content not included",15,MUTED));}
 void browse(String section){content.removeAllViews();content.addView(text(section,27,WHITE));if(channels.isEmpty()){content.addView(text("No channels imported. Check your provider and refresh in Settings.",16,MUTED));return;}EditText search=field("Search channels","");content.addView(search);ScrollView scroll=new ScrollView(this);content.addView(scroll);LinearLayout list=column();scroll.addView(list);Runnable render=()->{list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.US);int shown=0;for(Channel c:channels){if(!matches(c,section)||!c.name.toLowerCase(Locale.US).contains(q))continue;Button item=button(c.name+"   ·   "+c.group,()->play(c));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,58);lp.setMargins(4,3,4,3);list.addView(item,lp);if(++shown>=350)break;}if(shown==0)list.addView(text("No matching channels",17,MUTED));};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
 boolean matches(Channel c,String section){if(section.equals("Live TV"))return true;String s=(c.group+" "+c.name).toLowerCase(Locale.US);switch(section){case "Sports":return contains(s,"sport","espn","fox sports","nba","nfl","mlb","soccer","football","sky sport");case "News":return contains(s,"news","cnn","bbc","msnbc","fox news");case "Movies":return contains(s,"movie","cinema","film","hbo");case "Series":return contains(s,"series","shows","drama","episode");default:return true;}}
 boolean contains(String s,String... words){for(String w:words)if(s.contains(w))return true;return false;}
 void play(Channel c){root.removeAllViews();root.setBackgroundColor(Color.BLACK);VideoView video=new VideoView(this);root.addView(video,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);root.addView(bar);bar.addView(button("← Back",()->{video.stopPlayback();shell();browse("Live TV");}));bar.addView(text(c.name,19,WHITE));try{video.setVideoURI(android.net.Uri.parse(c.url));video.setOnPreparedListener(mp->mp.start());video.setOnErrorListener((mp,what,extra)->{Toast.makeText(this,"Playback failed. Provider stream may require a different codec or headers.",Toast.LENGTH_LONG).show();return true;});video.start();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 void load(String source){content.removeAllViews();content.addView(text("Importing channels in the background...",20,MUTED));new Thread(()->{try{ArrayList<Channel> parsed;if(!username.isEmpty()&&!password.isEmpty()){String base=source.replaceAll("/+$","");String api=base+"/player_api.php?username="+URLEncoder.encode(username,"UTF-8")+"&password="+URLEncoder.encode(password,"UTF-8");JSONObject auth=new JSONObject(fetch(api));if(!auth.optJSONObject("user_info").optString("auth","0").equals("1"))throw new Exception("Provider rejected credentials");JSONArray categories=new JSONArray(fetch(api+"&action=get_live_categories"));HashMap<String,String> map=new HashMap<>();for(int i=0;i<categories.length();i++){JSONObject o=categories.getJSONObject(i);map.put(o.optString("category_id"),o.optString("category_name","Other"));}JSONArray streams=new JSONArray(fetch(api+"&action=get_live_streams"));parsed=new ArrayList<>();for(int i=0;i<streams.length();i++){JSONObject o=streams.getJSONObject(i);String id=o.optString("stream_id");String ext=o.optString("container_extension","ts");String url=base+"/live/"+URLEncoder.encode(username,"UTF-8")+"/"+URLEncoder.encode(password,"UTF-8")+"/"+id+"."+ext;parsed.add(new Channel(o.optString("name","Channel"),url,map.getOrDefault(o.optString("category_id"),"Other")));}}else parsed=parseM3u(fetch(source));channels=parsed;handler.post(()->{shell();browse("Live TV");Toast.makeText(this,channels.size()+" channels imported",Toast.LENGTH_LONG).show();});}catch(Exception e){handler.post(()->{content.removeAllViews();content.addView(text("Import failed: "+e.getMessage(),18,WHITE));content.addView(button("Edit provider",this::login));});}}).start();}
 String fetch(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(25000);c.setRequestProperty("User-Agent","EStreamsBlue/1.0");try{int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("HTTP "+code);InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>80_000_000)throw new IOException("Playlist too large");}return out.toString("UTF-8");}finally{c.disconnect();}}
 ArrayList<Channel> parseM3u(String data){ArrayList<Channel> result=new ArrayList<>();String name="",group="Other";for(String line:data.split("\\r?\\n")){line=line.trim();if(line.startsWith("#EXTINF")){int comma=line.lastIndexOf(',');name=comma>=0?line.substring(comma+1).trim():"Channel";java.util.regex.Matcher m=java.util.regex.Pattern.compile("group-title=\"([^\"]*)\"").matcher(line);group=m.find()?m.group(1):"Other";}else if(line.startsWith("http://")||line.startsWith("https://")){result.add(new Channel(name.isEmpty()?"Channel":name,line,group));name="";group="Other";}}return result;}
}
